import * as Effect from "effect/Effect";import * as HttpRouter from "effect/http/HttpRouter";import * as HttpServerResponse from "effect/http/HttpServerResponse";import * as Layer from "effect/Layer";const {handler,dispose}=HttpRouter.toWebHandler(HttpRouter.add("GET","/hello",Effect.succeed(HttpServerResponse.text("hello"))),{disableLogger:true});handler(new Request("http://localhost/hello")).then(async(response:Response)=>{console.log(response.status,await response.text());await dispose()})
